function [f] = drag_box(lx, ly, lz)
%DRAG_BOX  dgeom.buildBox(Lx, Ly, Lz): the six drag panels of a box, +x into the wind.
%   lx: real[1] (passed a plain number)
%   ly: real[1] (passed a plain number)
%   lz: real[1] (passed a plain number)
%   returns f: ScFacets (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    f = asils.models.srp.ScFacets_zero();
    f = asils.models.srp.ScFacets_zero();
    z = [0; 0; 0];
    f = asils.models.srp.facet_add(f, 0, [1; 0; 0], (ly * lz), 0, 0, 0, z, false);
    f = asils.models.srp.facet_add(f, 0, [(-(1)); 0; 0], (ly * lz), 0, 0, 0, z, false);
    f = asils.models.srp.facet_add(f, 0, [0; 1; 0], (lx * lz), 0, 0, 0, z, false);
    f = asils.models.srp.facet_add(f, 0, [0; (-(1)); 0], (lx * lz), 0, 0, 0, z, false);
    f = asils.models.srp.facet_add(f, 0, [0; 0; 1], (lx * ly), 0, 0, 0, z, false);
    f = asils.models.srp.facet_add(f, 0, [0; 0; (-(1))], (lx * ly), 0, 0, 0, z, false);
end
